def analyze(g,label):
    H,W=len(g),len(g[0])
    # get big structure = all nonzeros within some large bbox; treat each connected component (4conn) separately
    seen=[[False]*W for _ in range(H)]; comps=[]
    for i in range(H):
        for j in range(W):
            if g[i][j] and not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True; cells=[]
                while st:
                    a,b=st.pop(); cells.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<H and 0<=nb<W and not seen[na][nb] and g[na][nb]:
                            seen[na][nb]=True; st.append((na,nb))
                comps.append(cells)
    print(label,'ncomps',len(comps),'sizes',[len(c) for c in comps])
    # try every pair of comps, all relative shifts, score agreement on overlapping cells
    for i in range(len(comps)):
        for j in range(i+1,len(comps)):
            A=set(comps[i]); B=set(comps[j])
            ar0=min(x[0] for x in A); ac0=min(x[1] for x in A)
            br0=min(x[0] for x in B); bc0=min(x[1] for x in B)
            for dr in range(-15,16):
                for dc in range(-25,26):
                    sc=sum(1 for (a,b) in A if (a-dr,b-dc) in B)
                    if sc>=max(len(A),len(B))*0.6:
                        pass
    return comps
